def choose_move(observation):
    wx, wy = observation['grid_width'], observation['grid_height']
    px, py = observation['self_position']
    opps = observation.get('opponent_position', [])
    resources = observation.get('resources', [])
    obstacles = observation.get('obstacles', [])
    score_self = observation['scores'][0]
    score_opp = observation['scores'][1]

    def dist(x, y):
        return abs(px - x) + abs(py - y)

    # Find nearest resource
    target = None
    min_dist = float('inf')
    for res in resources:
        dx, dy = res
        d = dist(dx, dy)
        if d < min_dist:
            min_dist, target = d, (dx, dy)

    # Decide move
    if target:
        dx = dy = 0
        if target[0] > px:
            dx = 1
        elif target[0] < px:
            dx = -1
        if target[1] > py:
            dy = 1
        elif target[1] < py:
            dy = -1
        # Check obstacles
        new_x, new_y = px + dx, py + dy
        if 0 <= new_x < wx and 0 <= new_y < wy and (new_x, new_y) not in obstacles:
            return [dx, dy]

    # Else, move toward opponent to contest, but keep safe distance (>1)
    if opps:
        ox, oy = opps
        delta_x = ox - px
        delta_y = oy - py
        # If too close, move away
        if abs(delta_x) <= 1 and abs(delta_y) <= 1:
            dx = -1 if delta_x > 0 else 1 if delta_x < 0 else 0
            dy = -1 if delta_y > 0 else 1 if delta_y < 0 else 0
            nx, ny = px + dx, py + dy
            if 0 <= nx < wx and 0 <= ny < wy and (nx, ny) not in obstacles:
                return [dx, dy]

    # Else, stay or move randomly
    for dx, dy in [[0,1], [0,-1], [1,0], [-1,0]]:
        nx, ny = px + dx, py + dy
        if 0 <= nx < wx and 0 <= ny < wy and (nx, ny) not in obstacles:
            return [dx, dy]

    return [0, 0]
